"""Export transactions as CSV/JSON, read JSON back, and draw fixed-width text tables."""

import json

from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import TallybookError, ValidationError
from tallybook.money import Money


class ExportError(ValidationError):
    """A table, export or import-from-JSON request that cannot be honoured."""


# ---------------------------------------------------------------- JSON helpers


def to_json(value):
    """The project's JSON text for ``value``: sorted keys, indent 2, UTF-8 friendly, one final newline."""
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    """``{"amount": "12.50", "currency": "USD"}`` for a Money, ``None`` for ``None``."""
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def _clean_tags(tags):
    return sorted(set(tags))


def transaction_to_dict(tx):
    """One transaction as the JSON-able dict of the export format."""
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _clean_tags(tx.tags),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
            for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    """A JSON array with one object per transaction, in the given order."""
    return to_json([transaction_to_dict(tx) for tx in txs])


# ------------------------------------------------------------------------ CSV


def _csv_field(cell):
    text = "" if cell is None else str(cell)
    if any(ch in text for ch in ',"\r\n'):
        text = '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    """CSV text: the header record, then one record per row; ``None`` cells are empty fields."""
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    """One CSV record per posting (a posting-less transaction gives one record)."""
    rows = []
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            format_date(tx.date),
            tx.flag,
            tx.payee,
            tx.narration,
            ";".join(_clean_tags(tx.tags)),
        ]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                amount, cur = "", ""
            else:
                amount, cur = p.amount.amount_str(), p.amount.currency
            rows.append(head + [p.account, amount, cur, p.note])
    return to_csv(CSV_HEADERS, rows)


# ----------------------------------------------------------------- JSON import


def _fail(where, message):
    prefix = where + ": " if where else ""
    raise ExportError(prefix + message)


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _read_posting(item, where):
    from tallybook.model import Posting

    if not isinstance(item, dict):
        _fail(where, "posting is not an object")
    unknown = sorted(set(item) - _POSTING_KEYS)
    if unknown:
        _fail(where, "unknown key '%s'" % unknown[0])
    account = item.get("account")
    if "account" not in item or not isinstance(account, str):
        _fail(where, "account is missing or not text")
    note = item.get("note", "")
    if not isinstance(note, str):
        _fail(where, "note is not text")
    raw = item.get("amount")
    amount = None
    if raw is not None:
        if not isinstance(raw, dict) or set(raw) != {"amount", "currency"}:
            _fail(where, "amount must be null or an object with exactly the keys amount and currency")
        if not isinstance(raw["amount"], str) or not isinstance(raw["currency"], str):
            _fail(where, "amount and currency must be text")
        try:
            amount = Money.of(raw["amount"], raw["currency"])
        except TallybookError as exc:
            _fail(where, "invalid amount: " + exc.message)
    return Posting(account, amount, note)


def _read_transaction(item, where):
    from tallybook.model import Transaction

    if not isinstance(item, dict):
        _fail(where, "item is not an object")
    unknown = sorted(set(item) - _TX_KEYS)
    if unknown:
        _fail(where, "unknown key '%s'" % unknown[0])
    for key in ("date", "payee", "postings"):
        if key not in item:
            _fail(where, "missing key '%s'" % key)
    if not isinstance(item["date"], str):
        _fail(where, "date is not text")
    try:
        day = parse_date(item["date"])
    except DateError as exc:
        _fail(where, "invalid date: " + exc.message)
    tx_id = item.get("id")
    if tx_id is not None and (not _is_int(tx_id) or tx_id < 1):
        _fail(where, "id must be null or a whole number of at least 1")
    flag = item.get("flag", "*")
    if flag not in ("*", "!") or not isinstance(flag, str):
        _fail(where, "flag must be '*' or '!'")
    payee = item["payee"]
    narration = item.get("narration", "")
    if not isinstance(payee, str):
        _fail(where, "payee is not text")
    if not isinstance(narration, str):
        _fail(where, "narration is not text")
    tags = item.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        _fail(where, "tags must be a list of text")
    if not isinstance(item["postings"], list):
        _fail(where, "postings must be a list")
    postings = [
        _read_posting(p, "%s posting %d" % (where, n)) for n, p in enumerate(item["postings"], 1)
    ]
    return Transaction(day, payee, narration, postings, tuple(_clean_tags(tags)), flag, tx_id)


def transactions_from_json(text):
    """Read the text made by ``transactions_to_json`` back into a list of Transactions."""
    if not isinstance(text, str):
        _fail("", "the JSON text must be a string")
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as exc:
        _fail("", "not valid JSON: %s" % exc)
    if not isinstance(data, list):
        _fail("", "the JSON is not an array")
    return [_read_transaction(item, "transaction %d" % n) for n, item in enumerate(data, 1)]


# ---------------------------------------------------------------------- tables


def _cell_text(cell):
    if cell is None:
        return ""
    text = str(cell)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    """Fixed-width text: titles, a rule, then the rows; two spaces between columns."""
    headers = [_cell_text(h) for h in headers]
    if not headers:
        return ""
    count = len(headers)
    if align is None:
        letters = ["l"] * count
    elif isinstance(align, (str, list, tuple)):
        letters = list(align)
    else:
        raise ExportError("align must be text or a list of 'l' and 'r'")
    if len(letters) != count or any(a not in ("l", "r") for a in letters):
        raise ExportError("align must hold one 'l' or 'r' for each of the %d columns" % count)
    body = []
    for number, row in enumerate(rows, 1):
        cells = [_cell_text(c) for c in row]
        if len(cells) != count:
            raise ExportError("row %d has %d cells, expected %d" % (number, len(cells), count))
        body.append(cells)
    widths = [len(h) for h in headers]
    for cells in body:
        for i, cell in enumerate(cells):
            widths[i] = max(widths[i], len(cell))

    def line(cells):
        parts = [
            cell.rjust(widths[i]) if letters[i] == "r" else cell.ljust(widths[i])
            for i, cell in enumerate(cells)
        ]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(cells) for cells in body)
    return "".join(out)

