"""The six reports (plain dicts), their text rendering and their CSV form."""

import datetime

from tallybook.currency import currency as _known_currency
from tallybook.dates import Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_csv
from tallybook.money import Money, format_minor, round_div

_TYPES = {"Assets": "asset", "Liabilities": "liability", "Equity": "equity", "Income": "income",
          "Expenses": "expense"}
_REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")


class ReportError(ValidationError):
    """A report that cannot be made from what was asked for."""


# -------------------------------------------------------------------- helpers


def _type_of(path):
    return _TYPES.get(path.split(":", 1)[0])


def _mdict(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _mlist(totals):
    """Money dicts for a ``{currency: minor}`` mapping, sorted by currency."""
    return [_mdict(totals[c], c) for c in sorted(totals)]


def _check_date(value, name, optional=True):
    if value is None and optional:
        return
    if not isinstance(value, datetime.date) or isinstance(value, datetime.datetime):
        raise ReportError("%s must be a date" % name)


def _check_period(period):
    if not isinstance(period, Period):
        raise ReportError("period must be a Period")


def _dstr(day):
    return None if day is None else format_date(day)


def _entries(ledger):
    """Every posting with an amount as ``(date, id, seq, tx, account, currency, minor)``."""
    out = []
    for tx in ledger.transactions():
        for seq, p in enumerate(tx.postings):
            if p.amount is not None:
                out.append((tx.date, tx.id, seq, tx, p.account, p.amount.currency, p.amount.minor))
    return out


def _percent_text(part, total):
    """``part / total * 100`` to one decimal, half away from zero."""
    if total == 0:
        return "0.0"
    tenths = round_div(part * 1000, total) if total > 0 else round_div(-part * 1000, -total)
    sign = "-" if tenths < 0 else ""
    return "%s%d.%d" % (sign, abs(tenths) // 10, abs(tenths) % 10)


def _check_convert(convert_to):
    if convert_to is not None:
        _known_currency(convert_to)


def _convert(ledger, cur, minor, target, on):
    """Convert one amount; amounts already in ``target`` are untouched."""
    if cur == target:
        return minor
    return ledger.rates.convert(Money(minor, cur), target, on).minor


def _sum_by_currency(pairs):
    totals = {}
    for cur, minor in pairs:
        totals[cur] = totals.get(cur, 0) + minor
    return totals


# --------------------------------------------------------------- trial balance


def trial_balance(ledger, as_of=None):
    _check_date(as_of, "as_of")
    sums = {}
    for day, _id, _seq, _tx, account, cur, minor in _entries(ledger):
        if as_of is None or day <= as_of:
            sums[(account, cur)] = sums.get((account, cur), 0) + minor
    accounts = []
    debits, credits = {}, {}
    for (account, cur) in sorted(sums):
        minor = sums[(account, cur)]
        if minor == 0:
            continue
        debit = credit = None
        if minor > 0:
            debit = _mdict(minor, cur)
            debits[cur] = debits.get(cur, 0) + minor
            credits.setdefault(cur, 0)
        else:
            credit = _mdict(-minor, cur)
            credits[cur] = credits.get(cur, 0) - minor
            debits.setdefault(cur, 0)
        accounts.append({"account": account, "type": _type_of(account), "debit": debit, "credit": credit})
    totals = [{"currency": c, "debit": _mdict(debits[c], c), "credit": _mdict(credits[c], c),
               "balanced": debits[c] == credits[c]} for c in sorted(debits)]
    return {"report": "trial_balance", "as_of": _dstr(as_of), "accounts": accounts, "totals": totals}


# --------------------------------------------------------------- balance sheet


def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_date(as_of, "as_of")
    _check_convert(convert_to)
    if convert_to is not None and as_of is None:
        raise ReportError("converting to %s needs an as_of date" % convert_to)
    sums = {}
    retained = {}
    for day, _id, _seq, _tx, account, cur, minor in _entries(ledger):
        if as_of is not None and day > as_of:
            continue
        kind = _type_of(account)
        if kind in ("income", "expense"):
            retained[cur] = retained.get(cur, 0) - minor
        else:
            sums[(account, cur)] = sums.get((account, cur), 0) + minor
    sections = {"asset": [], "liability": [], "equity": []}
    for (account, cur) in sorted(sums):
        minor = sums[(account, cur)]
        kind = _type_of(account)
        if minor == 0 or kind not in sections:
            continue
        sections[kind].append((account, cur, minor if kind == "asset" else -minor))
    retained = {c: v for c, v in retained.items() if v != 0}

    def build(kind, extra=None):
        lines = sections[kind]
        if convert_to is None:
            total = _sum_by_currency([(c, m) for _a, c, m in lines] + list((extra or {}).items()))
            return ([{"account": a, "balance": _mdict(m, c)} for a, c, m in lines], _mlist(total))
        out, total = [], 0
        for a, c, m in lines:
            conv = _convert(ledger, c, m, convert_to, as_of)
            out.append({"account": a, "balance": _mdict(conv, convert_to), "original": _mdict(m, c)})
            total += conv
        for c, m in (extra or {}).items():
            total += _convert(ledger, c, m, convert_to, as_of)
        return out, [_mdict(total, convert_to)]

    assets, assets_total = build("asset")
    liabilities, liabilities_total = build("liability")
    equity, equity_total = build("equity", retained)
    if convert_to is None:
        retained_list = _mlist(retained)
    elif retained:
        conv = sum(_convert(ledger, c, m, convert_to, as_of) for c, m in retained.items())
        retained_list = [_mdict(conv, convert_to)]
    else:
        retained_list = []

    def as_map(lst):
        return {m["currency"]: int(m["amount"].replace(".", "")) for m in lst}

    a_map, l_map, e_map = as_map(assets_total), as_map(liabilities_total), as_map(equity_total)
    balanced = all(a_map.get(c, 0) == l_map.get(c, 0) + e_map.get(c, 0)
                   for c in set(a_map) | set(l_map) | set(e_map))
    return {
        "report": "balance_sheet", "as_of": _dstr(as_of), "currency": convert_to,
        "assets": {"accounts": assets, "total": assets_total},
        "liabilities": {"accounts": liabilities, "total": liabilities_total},
        "equity": {"accounts": equity, "retained_earnings": retained_list, "total": equity_total},
        "balanced": balanced,
    }


# ------------------------------------------------------------ income statement


def income_statement(ledger, period, convert_to=None):
    _check_period(period)
    _check_convert(convert_to)
    sums = {}
    for day, _id, _seq, _tx, account, cur, minor in _entries(ledger):
        if period.start <= day <= period.end:
            kind = _type_of(account)
            if kind in ("income", "expense"):
                sums[(account, cur)] = sums.get((account, cur), 0) + (-minor if kind == "income" else minor)
    lines = {"income": [], "expense": []}
    for (account, cur) in sorted(sums):
        if sums[(account, cur)] != 0:
            lines[_type_of(account)].append((account, cur, sums[(account, cur)]))

    def section(kind):
        raw = lines[kind]
        if convert_to is None:
            items = [(a, c, m, None) for a, c, m in raw]
        else:
            items = [(a, convert_to, _convert(ledger, c, m, convert_to, period.end), _mdict(m, c))
                     for a, c, m in raw]
        totals = _sum_by_currency([(c, m) for _a, c, m, _o in items])
        if convert_to is not None:
            totals = {convert_to: totals.get(convert_to, 0)}
        out = []
        for a, c, m, original in items:
            line = {"account": a, "amount": _mdict(m, c), "percent": _percent_text(m, totals[c])}
            if original is not None:
                line["original"] = original
            out.append(line)
        return out, totals

    income, income_totals = section("income")
    expenses, expense_totals = section("expense")
    net = {c: income_totals.get(c, 0) - expense_totals.get(c, 0)
           for c in set(income_totals) | set(expense_totals)}
    return {
        "report": "income_statement", "start": format_date(period.start), "end": format_date(period.end),
        "currency": convert_to,
        "income": {"accounts": income, "total": _mlist(income_totals)},
        "expenses": {"accounts": expenses, "total": _mlist(expense_totals)},
        "net": _mlist(net),
    }


# -------------------------------------------------------------------- cashflow


def cashflow(ledger, period):
    _check_period(period)
    opening, closing, currencies = {}, {}, set()
    moves = {}
    for tx in ledger.transactions():
        if tx.date > period.end:
            continue
        assets = {}
        for p in tx.postings:
            if p.amount is None:
                continue
            cur = p.amount.currency
            if _type_of(p.account) == "asset":
                currencies.add(cur)
                closing[cur] = closing.get(cur, 0) + p.amount.minor
                if tx.date < period.start:
                    opening[cur] = opening.get(cur, 0) + p.amount.minor
                assets[cur] = assets.get(cur, 0) + p.amount.minor
        if tx.date < period.start:
            continue
        for p in tx.postings:
            if p.amount is None or _type_of(p.account) == "asset":
                continue
            cur = p.amount.currency
            if assets.get(cur, 0) != 0:
                key = (p.account, cur)
                moves[key] = moves.get(key, 0) - p.amount.minor
    inflows, outflows = [], []
    total_in = {c: 0 for c in currencies}
    total_out = {c: 0 for c in currencies}
    for (account, cur) in sorted(moves):
        value = moves[(account, cur)]
        if value > 0:
            inflows.append({"account": account, "amount": _mdict(value, cur)})
            total_in[cur] = total_in.get(cur, 0) + value
        elif value < 0:
            outflows.append({"account": account, "amount": _mdict(-value, cur)})
            total_out[cur] = total_out.get(cur, 0) - value
    net = {c: total_in[c] - total_out[c] for c in currencies}
    return {
        "report": "cashflow", "start": format_date(period.start), "end": format_date(period.end),
        "opening": _mlist({c: opening.get(c, 0) for c in currencies}),
        "inflows": inflows, "outflows": outflows,
        "total_in": _mlist(total_in), "total_out": _mlist(total_out), "net": _mlist(net),
        "closing": _mlist({c: closing.get(c, 0) for c in currencies}),
    }


# -------------------------------------------------------------------- register


def register(ledger, account, period=None, rollup=False):
    if period is not None:
        _check_period(period)
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))
    prefix = account + ":"
    chosen = [e for e in _entries(ledger)
              if e[4] == account or (rollup and e[4].startswith(prefix))]
    chosen.sort(key=lambda e: (e[0], e[1], e[2]))
    opening, running, currencies = {}, {}, set()
    rows = []
    for day, tx_id, _seq, tx, acct, cur, minor in chosen:
        if period is not None and day > period.end:
            continue
        currencies.add(cur)
        if period is not None and day < period.start:
            opening[cur] = opening.get(cur, 0) + minor
            running[cur] = running.get(cur, 0) + minor
            continue
        running[cur] = running.get(cur, 0) + minor
        rows.append({"date": format_date(day), "id": tx_id, "payee": tx.payee, "narration": tx.narration,
                     "account": acct, "amount": _mdict(minor, cur), "balance": _mdict(running[cur], cur)})
    return {
        "report": "register", "account": account, "rollup": bool(rollup),
        "start": _dstr(period.start if period else None), "end": _dstr(period.end if period else None),
        "opening": _mlist({c: opening.get(c, 0) for c in currencies}), "rows": rows,
        "closing": _mlist({c: running.get(c, 0) for c in currencies}),
    }


# ------------------------------------------------------------------- net worth


def net_worth(ledger, period, step="month"):
    _check_period(period)
    if step not in ("week", "month", "quarter", "year"):
        raise ReportError("unknown step %r: use week, month, quarter or year" % (step,))
    chosen = [e for e in _entries(ledger) if _type_of(e[4]) in ("asset", "liability")]
    chosen.sort(key=lambda e: e[0])
    assets, liabilities, seen = {}, {}, set()
    index = 0
    points = []
    for step_period in periods(period.start, period.end, step):
        until = step_period.end
        while index < len(chosen) and chosen[index][0] <= until:
            _d, _i, _s, _tx, account, cur, minor = chosen[index]
            seen.add(cur)
            target = assets if _type_of(account) == "asset" else liabilities
            target[cur] = target.get(cur, 0) + minor
            index += 1
        a = {c: assets.get(c, 0) for c in seen}
        li = {c: -liabilities.get(c, 0) for c in seen}
        points.append({"date": format_date(until), "assets": _mlist(a), "liabilities": _mlist(li),
                       "net": _mlist({c: a[c] - li[c] for c in seen})})
    return {"report": "net_worth", "start": format_date(period.start), "end": format_date(period.end),
            "step": step, "points": points}


# ------------------------------------------------------------------------- CSV


def _check_report(report):
    if not isinstance(report, dict) or report.get("report") not in _REPORTS:
        raise ReportError("not a report")
    return report["report"]


def _amount_cell(money):
    return "" if money is None else money["amount"]


def report_to_csv(report):
    """The table part of any report as CSV."""
    kind = _check_report(report)
    try:
        if kind == "trial_balance":
            rows = []
            for e in report["accounts"]:
                side = e["debit"] or e["credit"]
                rows.append([e["account"], e["type"], side["currency"], _amount_cell(e["debit"]),
                             _amount_cell(e["credit"])])
            return to_csv(["account", "type", "currency", "debit", "credit"], rows)
        if kind == "balance_sheet":
            rows = []
            for name in ("assets", "liabilities", "equity"):
                for line in report[name]["accounts"]:
                    rows.append([name, line["account"], line["balance"]["currency"], line["balance"]["amount"]])
            for m in report["equity"]["retained_earnings"]:
                rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
            return to_csv(["section", "account", "currency", "balance"], rows)
        if kind == "income_statement":
            rows = []
            for name in ("income", "expenses"):
                for line in report[name]["accounts"]:
                    rows.append([name, line["account"], line["amount"]["currency"], line["amount"]["amount"],
                                 line["percent"]])
            return to_csv(["section", "account", "currency", "amount", "percent"], rows)
        if kind == "cashflow":
            rows = [["opening", "", m["currency"], m["amount"]] for m in report["opening"]]
            rows += [["in", e["account"], e["amount"]["currency"], e["amount"]["amount"]] for e in report["inflows"]]
            rows += [["out", e["account"], e["amount"]["currency"], e["amount"]["amount"]] for e in report["outflows"]]
            rows += [["closing", "", m["currency"], m["amount"]] for m in report["closing"]]
            return to_csv(["section", "account", "currency", "amount"], rows)
        if kind == "register":
            rows = [[r["date"], r["id"], r["payee"], r["narration"], r["account"], r["amount"]["currency"],
                     r["amount"]["amount"], r["balance"]["amount"]] for r in report["rows"]]
            return to_csv(["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows)
        rows = []
        for point in report["points"]:
            nets = {m["currency"]: m for m in point["net"]}
            liabs = {m["currency"]: m for m in point["liabilities"]}
            for m in point["assets"]:
                c = m["currency"]
                rows.append([point["date"], c, m["amount"], liabs[c]["amount"], nets[c]["amount"]])
        return to_csv(["date", "currency", "assets", "liabilities", "net"], rows)
    except (KeyError, TypeError, AttributeError) as exc:
        raise ReportError("malformed report: %s" % (exc,))


# ------------------------------------------------------------------- text form


def _money_text(m):
    return "%s %s" % (m["amount"], m["currency"])


def _blocks(blocks, columns):
    """Rows of every non-empty block, one row of empty cells between two blocks."""
    rows = []
    for block in blocks:
        if block:
            if rows:
                rows.append([""] * columns)
            rows.extend(block)
    return rows


def _text(title, headers, rows, align):
    return title + "\n\n" + render_table(headers, rows, align)


def _render_trial_balance(r):
    title = "Trial balance" + (" as of " + r["as_of"] if r["as_of"] else "")
    rows = [[e["account"], e["type"], _money_text(e["debit"]) if e["debit"] else "",
             _money_text(e["credit"]) if e["credit"] else ""] for e in r["accounts"]]
    rows += [["Total", "", _money_text(t["debit"]), _money_text(t["credit"])] for t in r["totals"]]
    return _text(title, ["Account", "Type", "Debit", "Credit"], rows, "llrr")


def _render_balance_sheet(r):
    title = "Balance sheet" + (" as of " + r["as_of"] if r["as_of"] else "")
    if r["currency"]:
        title += " (in %s)" % r["currency"]

    def block(heading, section, total_label, retained=False):
        rows = [[heading, ""]]
        rows += [["  " + a["account"], _money_text(a["balance"])] for a in section["accounts"]]
        if retained:
            rows += [["  Retained earnings", _money_text(m)] for m in section["retained_earnings"]]
        rows += [[total_label, _money_text(m)] for m in section["total"]]
        return rows

    rows = _blocks([block("Assets", r["assets"], "Total assets"),
                    block("Liabilities", r["liabilities"], "Total liabilities"),
                    block("Equity", r["equity"], "Total equity", True)], 2)
    return _text(title, ["Account", "Balance"], rows, "lr")


def _render_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r["currency"]:
        title += " (in %s)" % r["currency"]

    def block(heading, section, total_label):
        rows = [[heading, "", ""]]
        rows += [["  " + a["account"], _money_text(a["amount"]), a["percent"] + "%"] for a in section["accounts"]]
        rows += [[total_label, _money_text(m), ""] for m in section["total"]]
        return rows

    rows = _blocks([block("Income", r["income"], "Total income"),
                    block("Expenses", r["expenses"], "Total expenses"),
                    [["Net income", _money_text(m), ""] for m in r["net"]]], 3)
    return _text(title, ["Account", "Amount", "Percent"], rows, "lrr")


def _render_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])

    def flow(heading, items, total_label, totals):
        rows = [[heading, ""]]
        rows += [["  " + e["account"], _money_text(e["amount"])] for e in items]
        rows += [[total_label, _money_text(m)] for m in totals]
        return rows

    rows = _blocks([
        [["Opening balance", _money_text(m)] for m in r["opening"]],
        flow("Money in", r["inflows"], "Total money in", r["total_in"]),
        flow("Money out", r["outflows"], "Total money out", r["total_out"]),
        [["Net change", _money_text(m)] for m in r["net"]]
        + [["Closing balance", _money_text(m)] for m in r["closing"]],
    ], 2)
    return _text(title, ["Account", "Amount"], rows, "lr")


def _render_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for point in r["points"]:
        if not point["assets"]:
            rows.append([point["date"], "", "", ""])
            continue
        liabs = {m["currency"]: m for m in point["liabilities"]}
        nets = {m["currency"]: m for m in point["net"]}
        for m in point["assets"]:
            c = m["currency"]
            rows.append([point["date"], _money_text(m), _money_text(liabs[c]), _money_text(nets[c])])
    return _text(title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")


def _render_register(r):
    title = "Register " + r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _money_text(m)] for m in r["opening"]]
    rows += [[x["date"], "" if x["id"] is None else x["id"], x["payee"], x["account"],
              _money_text(x["amount"]), _money_text(x["balance"])] for x in r["rows"]]
    rows += [["", "", "Closing balance", "", "", _money_text(m)] for m in r["closing"]]
    return _text(title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")


_RENDERERS = {
    "trial_balance": _render_trial_balance, "balance_sheet": _render_balance_sheet,
    "income_statement": _render_income_statement, "cashflow": _render_cashflow,
    "net_worth": _render_net_worth, "register": _render_register,
}


def render_text(report):
    """Any report dict as its text form."""
    kind = _check_report(report)
    try:
        return _RENDERERS[kind](report)
    except (KeyError, TypeError, AttributeError) as exc:
        raise ReportError("malformed report: %s" % (exc,))
